  async function konfigNotif(el) {
    el.innerHTML = UI.kerangka(2, 200);
    const r = await API.call('notif.config', {});
    if (!r.success) { el.innerHTML = UI.galat(r); return; }
    const c = r.data;
    el.innerHTML = `<div class="grid g2"><div class="kartu"><div class="kartu-h"><h3>Kanal & gateway</h3></div><form id="f-nc" class="form">${F.formHtml([{ k: 'waAktif', l: 'WhatsApp', t: 'saklar', teksSaklar: 'Aktifkan notifikasi WhatsApp (Fonnte)' }, { k: 'emailAktif', l: 'Email', t: 'saklar', teksSaklar: 'Aktifkan notifikasi email (sisa kuota hari ini: ' + c.kuotaEmail + ')' }, { k: 'token', l: 'Token Fonnte', ph: c.tokenAda ? 'Tersimpan (' + c.token + ') — kosongkan bila tidak diganti' : 'Tempel token dari dashboard Fonnte', bantu: 'Disimpan di Script Properties, tidak pernah dikirim balik ke browser.' }, { k: 'batchDefault', l: 'Ukuran batch blast', t: 'pilih', opsi: ['10', '20', '50'], kosong: false }, { k: 'jeda', l: 'Jeda antarpesan (detik)', ph: '5 atau 3-8' }, { k: 'deteksiOtomatis', l: 'Deteksi nomor', t: 'saklar', teksSaklar: 'Cek otomatis nomor baru terdaftar di WhatsApp' }, { k: 'namaPengirim', l: 'Nama pengirim email' }, { k: 'appUrl', l: 'Alamat aplikasi (untuk tautan di pesan)', t: 'url', penuh: true }], { waAktif: c.waAktif, emailAktif: c.emailAktif, batchDefault: String(c.batchDefault), jeda: c.jeda, deteksiOtomatis: c.deteksiOtomatis, namaPengirim: c.namaPengirim, appUrl: c.appUrl })}<div class="aksi">${c.tokenAda ? '<button type="button" class="btn btn-hantu" id="b-hapus-token"><span class="ms">key_off</span>Hapus token</button>' : ''}<button class="btn btn-utama"><span class="ms">save</span>Simpan</button></div></form>${c.trigger ? '' : '<div class="banner banner-kuning" style="margin-top:12px"><span class="ms">schedule</span><div><b>Trigger antrean belum terpasang</b>Simpan konfigurasi ini atau jalankan pasangTrigger() dari editor.</div></div>'}</div>
      <div class="kartu"><div class="kartu-h"><h3>Uji kirim</h3></div><div class="form-grid"><div class="isian"><label>Nomor WA uji</label><input id="t-wa" placeholder="0812…" value="${esc(Sesi.me.wa || '')}"></div><div class="isian"><label>Email uji</label><input id="t-em" type="email" value="${esc(Sesi.me.email)}"></div></div><div class="baris-aksi" style="margin-top:10px"><button class="btn btn-hantu" id="b-dev"><span class="ms">smartphone</span>Cek perangkat Fonnte</button><button class="btn btn-hantu" id="b-twa"><span class="ms">chat</span>Tes WA</button><button class="btn btn-hantu" id="b-tem"><span class="ms">mail</span>Tes email</button></div><div id="h-dev" style="margin-top:12px"></div></div></div>
      <div class="kartu" style="margin-top:16px"><div class="kartu-h"><div><h3>Matriks notifikasi</h3><p>Pilih kanal per kejadian dan sesuaikan isi pesan. Placeholder seperti {nama}, {tautan}, {tenggat} diisi otomatis.</p></div><button class="btn btn-utama btn-kecil" id="b-mx"><span class="ms">save</span>Simpan matriks</button></div><div class="tbl-wrap"><table class="tbl matriks-notif"><thead><tr><th>Kejadian</th><th>WA</th><th>Email</th><th>Subjek & pesan</th></tr></thead><tbody>${c.matriks.map(m => '<tr data-kode="' + esc(m.kode) + '"><td><b>' + esc(m.label) + '</b><div class="catatan mono">' + esc(m.kode) + '</div></td><td><label class="saklar"><input type="checkbox" data-wa' + (m.wa ? ' checked' : '') + '><span></span></label></td><td><label class="saklar"><input type="checkbox" data-em' + (m.email ? ' checked' : '') + '><span></span></label></td><td style="min-width:320px"><input data-sj value="' + esc(m.subjek || '') + '" style="width:100%;margin-bottom:6px;border:1px solid var(--garis);border-radius:10px;padding:7px 9px;font:inherit;font-size:12.5px"><textarea data-ps>' + esc(m.pesan) + '</textarea>' + (m.pesan !== m.pesanDefault ? '<button type="button" class="btn btn-hantu btn-kecil" data-reset>Kembalikan bawaan</button>' : '') + '</td></tr>').join('')}</tbody></table></div></div>`;
    const f = $('#f-nc', el), FL = [{ k: 'waAktif', t: 'saklar' }, { k: 'emailAktif', t: 'saklar' }, { k: 'token' }, { k: 'batchDefault' }, { k: 'jeda' }, { k: 'deteksiOtomatis', t: 'saklar' }, { k: 'namaPengirim' }, { k: 'appUrl' }];
    const kirim = async (btn, extra) => { const v = F.bacaForm(f, FL); const data = Object.assign({}, v, { waAktif: v.waAktif === 'Ya', emailAktif: v.emailAktif === 'Ya', deteksiOtomatis: v.deteksiOtomatis === 'Ya', batchDefault: Number(v.batchDefault) }, extra || {}); if (!data.token) delete data.token; return UI.aksi(btn, 'notif.configSimpan', data, { lalu: () => konfigNotif(el) }); };
    f.onsubmit = e => { e.preventDefault(); kirim($('button.btn-utama', f)); };
    const bh = $('#b-hapus-token', el); if (bh) bh.onclick = async () => { const k = await UI.konfirmasi('Hapus token Fonnte', 'WhatsApp akan nonaktif sampai token baru diisi.', { bahaya: true, teksOk: 'Hapus' }); if (k.ok) kirim(bh, { token: '__HAPUS__', waAktif: false }); };
    $('#b-mx', el).onclick = e => { const matriks = $$('tr[data-kode]', el).map(tr => ({ kode: tr.dataset.kode, wa: $('[data-wa]', tr).checked, email: $('[data-em]', tr).checked, subjek: $('[data-sj]', tr).value, pesan: $('[data-ps]', tr).value })); kirim(e.currentTarget, { matriks }); };
    el.addEventListener('click', e => { const rs = e.target.closest('[data-reset]'); if (rs) { const tr = rs.closest('tr'), m = c.matriks.find(x => x.kode === tr.dataset.kode); $('[data-ps]', tr).value = m.pesanDefault; $('[data-sj]', tr).value = m.subjekDefault || ''; rs.remove(); } });
    $('#b-dev', el).onclick = async e => { const x = await UI.aksi(e.currentTarget, 'wa.device', {}, { diam: true }); if (x.success) $('#h-dev', el).innerHTML = '<div class="banner ' + (x.data.device_status === 'connect' ? 'banner-hijau' : 'banner-kuning') + '"><span class="ms">smartphone</span><div><b>' + esc(x.data.device || '-') + ' · ' + esc(x.data.device_status || '-') + '</b>Paket ' + esc(x.data.package || '-') + ' · kuota ' + esc(x.data.quota || '-') + (x.data.expired ? ' · berlaku s.d. ' + esc(x.data.expired) : '') + '</div></div>'; };
    $('#b-twa', el).onclick = e => UI.aksi(e.currentTarget, 'wa.test', { nomor: $('#t-wa', el).value });
    $('#b-tem', el).onclick = e => UI.aksi(e.currentTarget, 'email.test', { email: $('#t-em', el).value });
  }

  async function blast(el) {
    const st = await API.q('crm.list', { per: 1, halaman: 1 }); const segmen = st.success ? Object.keys(st.data.facet.segmen) : [];
    el.innerHTML = `<div class="grid g-8-4"><div class="kartu"><div class="kartu-h"><div><h3>Susun blast</h3><p>Penerima dari CRM Kontak (opt-out & nomor ganda otomatis dibuang) atau daftar manual.</p></div></div>
      <div class="form-grid"><div class="isian"><label>Sumber penerima</label><select id="b-src"><option value="crm">CRM Kontak</option><option value="manual">Daftar manual</option></select></div><div class="isian" data-crm><label>Segmen</label><select id="b-seg"><option value="">Semua segmen</option>${segmen.map(s => '<option>' + esc(s) + '</option>').join('')}</select></div><div class="isian" data-crm><label>Tag</label><input id="b-tag" placeholder="opsional"></div><div class="isian penuh" data-man hidden><label>Daftar nomor (satu per baris: 08xx|Nama)</label><textarea id="b-man" rows="5"></textarea></div></div>
      <div class="baris-aksi" style="margin-top:10px"><button class="btn btn-hantu" id="b-muat"><span class="ms">group</span>Muat penerima</button><button class="btn btn-hantu" id="b-cek" disabled><span class="ms">verified</span>Cek nomor terdaftar WA</button></div><div id="aud" style="margin-top:12px"></div>
      <div class="form-grid" style="margin-top:12px"><div class="isian penuh"><label>Judul blast (internal)</label><input id="b-jdl" placeholder="Pengumuman AMI Ganjil"></div><div class="isian penuh"><label>Pesan</label><textarea id="b-psn" rows="6" placeholder="Assalamu'alaikum {nama}, …"></textarea><small>{nama} diganti nama penerima. Gunakan *tebal* dan _miring_ ala WhatsApp.</small></div><div class="isian"><label>Ukuran batch</label><select id="b-ub"><option>10</option><option selected>20</option><option>50</option></select></div><div class="isian"><label>Jeda antarpesan (detik)</label><input id="b-jd" value="5"></div></div>
      <div class="aksi" style="margin-top:12px"><button class="btn btn-utama" id="b-buat" disabled><span class="ms">send</span>Buat blast</button></div></div>
      <div class="kartu"><div class="kartu-h"><h3>Blast terbaru</h3><button class="ikon-btn kecil" id="b-rf" aria-label="Segarkan"><span class="ms">refresh</span></button></div><div id="bl"></div></div></div>`;
    let aud = null, tmr = null;
    $('#b-src', el).onchange = () => { const m = $('#b-src', el).value === 'manual'; $$('[data-crm]', el).forEach(x => x.hidden = m); $$('[data-man]', el).forEach(x => x.hidden = !m); };
    const ring = () => { const r = aud.ringkas, kirim = aud.rows.filter(x => x.valid && !x.ganda && !x.optOut); $('#aud', el).innerHTML = '<div class="baris-aksi">' + chip(r.total + ' kontak', 'c-abu') + chip(kirim.length + ' akan dikirimi', 'c-hijau') + (r.tidakValid ? chip(r.tidakValid + ' nomor tidak valid', 'c-merah') : '') + (r.ganda ? chip(r.ganda + ' ganda', 'c-amber') : '') + (r.optOut ? chip(r.optOut + ' opt-out', 'c-abu') : '') + (r.terdaftarWA ? chip(r.terdaftarWA + ' terdaftar WA', 'c-teal') : '') + (r.tidakTerdaftarWA ? chip(r.tidakTerdaftarWA + ' tidak terdaftar WA', 'c-merah') : '') + '</div>'; $('#b-buat', el).disabled = !kirim.length; $('#b-cek', el).disabled = !kirim.length; return kirim; };
    $('#b-muat', el).onclick = async e => { const m = $('#b-src', el).value; const x = await UI.aksi(e.currentTarget, 'wa.audience', m === 'manual' ? { sumber: 'manual', teks: $('#b-man', el).value } : { sumber: 'crm', segmen: $('#b-seg', el).value, tag: $('#b-tag', el).value.trim() }, { diam: true }); if (x.success) { aud = x.data; ring(); } };
    $('#b-cek', el).onclick = async e => {
      const b = e.currentTarget, nomor = [...new Set(aud.rows.filter(x => x.valid).map(x => x.hp))]; let ok = 0;
      for (let i = 0; i < nomor.length; i += 50) { b.innerHTML = '<span class="ms">hourglass_top</span>Mengecek ' + Math.min(i + 50, nomor.length) + '/' + nomor.length; const x = await API.call('wa.validasi', { nomor: nomor.slice(i, i + 50) }); if (!x.success) { UI.toast(x.message, 'galat'); break; } Object.keys(x.data.hasil).forEach(h => aud.rows.filter(rr => rr.hp === h).forEach(rr => rr.statusWA = x.data.hasil[h])); ok += Object.keys(x.data.hasil).length; }
      b.innerHTML = '<span class="ms">verified</span>Cek nomor terdaftar WA'; aud.ringkas.terdaftarWA = aud.rows.filter(x => x.statusWA === 'Terdaftar').length; aud.ringkas.tidakTerdaftarWA = aud.rows.filter(x => x.statusWA === 'Tidak Terdaftar').length; ring(); if (ok) UI.toast(ok + ' nomor dicek.', 'sukses');
    };
    $('#b-buat', el).onclick = async e => {
      const kirim = ring().filter(x => x.statusWA !== 'Tidak Terdaftar');
      const k = await UI.konfirmasi('Buat blast WhatsApp', kirim.length + ' penerima akan dikirimi dalam ' + Math.ceil(kirim.length / Number($('#b-ub', el).value)) + ' batch. Batch pertama dikirim pada putaran antrean berikutnya (≤ 1 menit).', { teksOk: 'Buat blast' }); if (!k.ok) return;
      UI.aksi(e.currentTarget, 'wa.blastBuat', { judul: $('#b-jdl', el).value, pesan: $('#b-psn', el).value, ukuranBatch: Number($('#b-ub', el).value), jeda: $('#b-jd', el).value, sasaran: $('#b-src', el).value === 'crm' ? ($('#b-seg', el).value || 'Semua') + ($('#b-tag', el).value ? ' #' + $('#b-tag', el).value : '') : 'Manual', penerima: kirim.map(x => ({ hp: x.hp, nama: x.nama })) }, { lalu: () => daftar() });
    };
    const daftar = async () => {
      const x = await API.call('wa.blastList', {}); if (!x.success) { $('#bl', el).innerHTML = UI.galat(x); return; }
      $('#bl', el).innerHTML = x.data.length ? '<div class="daftar">' + x.data.slice(0, 15).map(b => '<div class="item" style="display:block"><div style="display:flex;justify-content:space-between;gap:8px"><b>' + esc(b.Judul) + '</b>' + chip(b.Status, b.Status === 'Berjalan' ? 'c-biru' : b.Status === 'Selesai' ? 'c-hijau' : 'c-abu') + '</div><small class="catatan">' + esc(Fmt.waktu(b.Tanggal)) + ' · ' + b.Terkirim + ' terkirim · ' + b.Gagal + ' gagal · sisa ' + b.sisa + ' / ' + b.Total + '</small>' + G.progres(b.persen, 'teal') + (b.Status === 'Berjalan' ? '<div class="baris-aksi" style="margin-top:6px"><button class="btn btn-hantu btn-kecil" data-pr="' + esc(b.ID) + '"><span class="ms">skip_next</span>Kirim batch berikutnya</button><button class="btn btn-hantu btn-kecil" data-stop="' + esc(b.ID) + '"><span class="ms">stop</span>Hentikan</button></div>' : '') + '</div>').join('') + '</div>' : UI.kosong('Belum ada blast.', 'campaign');
      clearTimeout(tmr); if (x.data.some(b => b.Status === 'Berjalan') && document.body.contains(el)) tmr = setTimeout(daftar, 20000);
    };
    $('#b-rf', el).onclick = daftar;
    $('#bl', el).addEventListener('click', async e => { const p = e.target.closest('[data-pr]'), s = e.target.closest('[data-stop]'); if (p) await UI.aksi(p, 'wa.blastProses', { id: p.dataset.pr }, { diam: true, lalu: daftar }); if (s) { const k = await UI.konfirmasi('Hentikan blast', 'Pesan yang belum terkirim dibatalkan.', { bahaya: true, teksOk: 'Hentikan' }); if (k.ok) UI.aksi(s, 'wa.blastStop', { id: s.dataset.stop }, { lalu: daftar }); } });
    daftar();
  }

  async function antrean(el) {
    el.innerHTML = '<div class="kartu"><div class="baris-aksi"><select id="q-st"><option value="">Semua status</option><option>Antri</option><option>Terkirim</option><option>Gagal</option><option>Batal</option></select><select id="q-kn"><option value="">Semua kanal</option><option>WA</option><option>EMAIL</option></select><span style="flex:1"></span><button class="btn btn-hantu btn-kecil" id="b-proses"><span class="ms">bolt</span>Proses antrean sekarang</button>' + (sa() ? '<button class="btn btn-hantu btn-kecil" id="b-ulang"><span class="ms">replay</span>Ulangi yang gagal</button>' : '') + '</div><div id="rk" style="margin:12px 0"></div><div id="t-q"></div></div>';
    const muatQ = async () => {
      const x = await API.call('notif.antrean', { status: $('#q-st', el).value, kanal: $('#q-kn', el).value }); if (!x.success) { $('#t-q', el).innerHTML = UI.galat(x); return; }
      const r = x.data.ringkas; $('#rk', el).innerHTML = '<div class="baris-aksi">' + chip(r.Antri + ' antri', 'c-biru') + chip(r.Terkirim + ' terkirim', 'c-hijau') + chip(r.Gagal + ' gagal', 'c-merah') + chip(r.Batal + ' batal', 'c-abu') + '</div>';
      tabel($('#t-q', el), { rows: x.data.rows, nama: 'Log notifikasi', kolom: [{ k: 'Waktu', l: 'Waktu', f: q => esc(Fmt.waktu(q.Waktu)) }, { k: 'Kanal', l: 'Kanal', f: q => chip(q.Kanal, q.Kanal === 'WA' ? 'c-hijau' : 'c-biru') }, { k: 'Penerima', l: 'Penerima', f: q => '<b>' + esc(q.Nama_Penerima || '') + '</b><div class="catatan mono">' + esc(q.Penerima) + '</div>' }, { k: 'Jenis_Pengingat', l: 'Kejadian', f: q => '<span class="mono catatan">' + esc(q.Jenis_Pengingat) + '</span>' }, { k: 'Isi', l: 'Isi', f: q => '<span class="catatan">' + esc(q.Subjek ? q.Subjek + ' — ' : '') + esc(q.Isi) + '</span>' }, { k: 'Status_Kirim', l: 'Status', f: q => chip(q.Status_Kirim, { Terkirim: 'c-hijau', Gagal: 'c-merah', Antri: 'c-biru' }[q.Status_Kirim] || 'c-abu') + (q.Respons_API && q.Status_Kirim === 'Gagal' ? '<div class="catatan">' + esc(String(q.Respons_API).slice(0, 80)) + '</div>' : '') }] });
    };
    $('#q-st', el).onchange = muatQ; $('#q-kn', el).onchange = muatQ;
    $('#b-proses', el).onclick = e => UI.aksi(e.currentTarget, 'notif.proses', {}, { lalu: muatQ });
    const bu = $('#b-ulang', el); if (bu) bu.onclick = e => UI.aksi(e.currentTarget, 'notif.ulangi', {}, { lalu: muatQ });
    muatQ();
  }

