        '<div class="grid g4" style="margin-top:14px" id="c-kpi">' + UI.kerangka(4, 90) + '</div><div class="kartu" style="margin-top:16px"><div class="tabel-alat"><div class="cari-tabel"><span class="ms">search</span><input id="c-q" type="search" placeholder="Cari nama, email, WA…"></div><select id="c-seg"><option value="">Semua segmen</option></select><select id="c-wa"><option value="">Status WA</option><option>Terdaftar</option><option>Tidak Terdaftar</option><option>Belum dicek</option></select><select id="c-x"><option value="">Semua</option><option value="optOut">Opt-out</option><option value="duplikat">Duplikat</option><option value="masalah">Data bermasalah</option></select><span class="spacer"></span><select id="c-bulk" disabled><option value="">Aksi terpilih…</option><option value="tag">Tambah tag</option><option value="untag">Hapus tag</option><option value="optout">Opt-out</option><option value="optin">Opt-in</option><option value="deteksiWA">Cek WA</option><option value="gabung">Gabungkan duplikat</option><option value="hapusManual">Hapus (manual)</option></select></div><div id="c-t"></div><div class="paginasi" id="c-pg"></div></div>';
